+package com.example;
+
+import com.example.MessageStore.SentMessage;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private final MessageStore messageStore;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<SentMessage> grid = new Grid<>();
+    private boolean resetting;
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        setPadding(true);
+        setSpacing(true);
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        FormLayout form = new FormLayout();
+        form.add(name, email, phone, message);
+        message.setMinHeight("140px");
+
+        send.addThemeVariants(ButtonVariant.PRIMARY);
+        send.addClickListener(event -> submit());
+        send.addClickShortcut(com.vaadin.flow.component.Key.ENTER);
+        form.add(send);
+
+        add(form);
+        configureEditingListeners();
+        configureGrid();
+    }
+
+    private void configureEditingListeners() {
+        name.addValueChangeListener(event -> edited());
+        email.addValueChangeListener(event -> edited());
+        phone.addValueChangeListener(event -> edited());
+        message.addValueChangeListener(event -> edited());
+    }
+
+    private void edited() {
+        if (!resetting) {
+            send.setEnabled(true);
+            clearValidation();
+        }
+    }
+
+    private void configureGrid() {
+        grid.addColumn(SentMessage::name).setHeader("Name");
+        grid.addColumn(SentMessage::message).setHeader("Message");
+        grid.setItems(messageStore.getMessages());
+        grid.setWidthFull();
+        add(grid);
+    }
+
+    private void submit() {
+        clearValidation();
+
+        boolean valid = true;
+        if (name.getValue().isBlank()) {
+            invalidate(name, "Name is required");
+            valid = false;
+        }
+
+        boolean hasEmail = !email.getValue().isBlank();
+        boolean hasPhone = !phone.getValue().isBlank();
+        if (hasEmail && !email.getValue().matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")) {
+            invalidate(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (!hasEmail && !hasPhone) {
+            invalidate(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (message.getValue().isBlank()) {
+            invalidate(message, "Message is required");
+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            invalidate(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(name.getValue(), email.getValue(), phone.getValue(), message.getValue());
+        grid.setItems(messageStore.getMessages());
+        Notification.show("Message sent");
+
+        resetting = true;
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        resetting = false;
+        send.setEnabled(false);
+    }
+
+    private void invalidate(TextField field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(true);
+    }
+
+    private void invalidate(EmailField field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(true);
+    }
+
+    private void invalidate(TextArea field, String error) {
+        field.setErrorMessage(error);
+        field.setInvalid(true);
+    }
+
+    private void clearValidation() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private boolean hasDraft() {
+        return !name.getValue().isEmpty()
+                || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty()
+                || !message.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasDraft()) {
+            return;
+        }
+
+        var action = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.add(new Span("You have an unfinished message. Leave this page?"));
+
+        Button keepEditing = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            action.proceed();
+        });
+        HorizontalLayout buttons = new HorizontalLayout(keepEditing, discard);
+        dialog.add(buttons);
+        dialog.open();
+    }
+}
