+package com.example;
+
+import java.util.ArrayList;
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Service;
+
+@Service
+public class MessageStore {
+
+    private final CopyOnWriteArrayList<SentMessage> messages = new CopyOnWriteArrayList<>();
+
+    public void add(String name, String email, String phone, String message) {
+        messages.add(0, new SentMessage(name, email, phone, message));
+    }
+
+    public List<SentMessage> getMessages() {
+        return new ArrayList<>(messages);
+    }
+
+    public record SentMessage(String name, String email, String phone, String message) {
+    }
+}
